# 2017 Q6 source page has an unreadable question body; preserve it in review.
for q in qs:
 if q['type']=='MCQ':
  year=int(q['year']);n=q['number'];a=mcq.get(year,{}).get(n)
  if a:
   topics,why=a;q['primaryTopic']=topics[0];q['relatedTopics']=topics;q['topicName']=None;q['secondaryTopics']=topics[1:];q['classificationRationale']=why;q['classificationMethod']='Question-content review against current CED; scanned page checked';q['evidencePages']=q['sourcePagesOriginal'];q['status']='classified';q['reviewReason']=None
 elif q['type']=='FRQ':
  year=int(q['year']);key=(year,q['number']);a=frqs.get(key)
  if a:
   topics,why,parts=a;q['primaryTopic']=topics[0];q['relatedTopics']=topics;q['classificationRationale']=why;q['classificationMethod']='Question-part review against current CED; original scan checked';q['topicParts']=[{'label':label,'topics':t,'topicNames':[],'rationale':r,'textPreview':r} for label,t,r in parts];q['multiConcept']=len(topics)>1;q['status']='classified';q['reviewReason']=None;q['legacyConcepts']=[]
(R/'scanned-classified.json').write_text(json.dumps(qs,ensure_ascii=False,indent=1))
print('new scan records',len(qs),'classified',sum(q['status']=='classified' for q in qs),'review',sum(q['status']=='review' for q in qs))
